-- SKAI-1806 (DB-01 Phase 0b): index every foreign key column.
-- Postgres does not index the referencing side of a foreign key. Without these, joins from a parent
-- (marks by student, attendance by enrollment, invoices by enrollment...) and every parent delete scan the
-- whole child table. Indexes only: no column, constraint or data change. `scripts/check-fk-indexes.mjs`
-- keeps the schema at zero unindexed foreign keys.
--
-- Plain CREATE INDEX briefly blocks writes on each table while it builds; current tables are small.
-- For a large production table, build its index first with CREATE INDEX CONCURRENTLY using the same name:
-- IF NOT EXISTS then skips it here. Rollback: DROP INDEX for the names below.

CREATE INDEX IF NOT EXISTS "rag_chunks_document_id_school_id_idx" ON "rag_chunks"("document_id", "school_id");
